package br.com.fiap.bank.plataforma.infrastructure.client;
import br.com.fiap.bank.plataforma.domain.CoreBancarioGateway; import org.springframework.stereotype.Component; import java.util.*; @Component public class CoreBancarioGatewayAdapter implements CoreBancarioGateway { private final CoreBancarioFeignClient client; public CoreBancarioGatewayAdapter(CoreBancarioFeignClient c){client=c;} public Map<String,Object> consultarContaCliente(String cpf){try{return client.consultarContaCliente(cpf);}catch(Exception e){return Map.of("statusConta","INDISPONIVEL","mensagem","Core Bancário indisponível ou conta não encontrada.");}} }
